cd /home/user/project/output && python3 -c "
import re, os
for root, dirs, files in os.walk('.'):
    for f in files:
        if f.endswith('.md'):
            p = os.path.join(root, f)
            text = open(p).read()
            for m in re.finditer(r'\[([^\]]+)\]\(([^)]+)\)', text):
                target = m.group(2)
                resolved = os.path.normpath(os.path.join(root, target))
                ok = os.path.isfile(resolved)
                print(p, '->', m.group(1), target, resolved, 'OK' if ok else 'MISSING')
"
